class Student:
    def __init__(self, student_id: int, name: str, grades: list = None):
        self.student_id = student_id
        self.name = name
        self.grades = grades if grades is not None else []

    def add_grade(self, grade: float):
        if 0 <= grade <= 100:
            self.grades.append(grade)

    def get_gpa(self) -> float:
        return round(sum(self.grades) / len(self.grades), 2) if self.grades else 0.0

    def to_dict() -> dict:
        return {
            "id": self.student_id,
            "name": self.name,
            "grades": self.grades,
            "gpa": self.get_gpa()
        }

class StudentManager:
    def __init__(self):
        self.students = {}

    def register_student(self, student_id: int, name: str) -> Student:
        student = Student(student_id, name)
        self.students[student_id] = student
        return student

    def get_top_students(self, min_gpa: float = 85.0) -> list:
        return [s.to_dict() for s in self.students.values() if s.get_gpa() >= min_gpa]

manager = StudentManager()
s1 = manager.register_student(101, 'Alex River')
s1.add_grade(95.0)
s1.add_grade(90.0)

s2 = manager.register_student(102, 'Sarah Smith')
s2.add_grade(75.0)

print("Top Students (GPA >= 85):", manager.get_top_students(85.0))
